using System;
using System.Data;
using System.IO;
using System.Web;
using iTextSharp.text;
using iTextSharp.text.pdf;

namespace InformationWeb.Controls.Sims
{
    public class PdfReportHelper
    {
        private const string FONT_PATH = "~\\Media\\SVN-Times New Roman4.ttf";

        public static BaseFont CreateBaseFont(HttpServerUtility server)
        {
            string fontPath = server.MapPath(FONT_PATH);
            return BaseFont.CreateFont(fontPath, BaseFont.IDENTITY_H, BaseFont.NOT_EMBEDDED);
        }

        public static Document InitDocument(out PdfWriter writer, out MemoryStream memoryStream)
        {
            Document pdfDoc = new Document(PageSize.A4, 20f, 20f, 30f, 30f);
            memoryStream = new MemoryStream();
            writer = PdfWriter.GetInstance(pdfDoc, memoryStream);
            writer.CloseStream = false;
            return pdfDoc;
        }

        public static PdfPTable BuildSchoolHeader(BaseFont baseFont, DataTable dtb)
        {
            PdfPTable h1 = new PdfPTable(2);
            h1.WidthPercentage = 100;
            h1.SetWidths(new float[] { 6f, 4f });

            PdfPCell A1 = new PdfPCell(new Phrase("TRƯỜNG CAO ĐẲNG CƠ ĐIỆN - XÂY DỰNG VÀ NÔNG LÂM TRUNG BỘ", new Font(baseFont, 10, Font.BOLD)));
            A1.Border = Rectangle.NO_BORDER;
            A1.HorizontalAlignment = Element.ALIGN_CENTER;
            A1.VerticalAlignment = Element.ALIGN_MIDDLE;
            h1.AddCell(A1);

            PdfPCell T1 = new PdfPCell(new Phrase("CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM", new Font(baseFont, 10, Font.BOLD)));
            T1.Border = Rectangle.NO_BORDER;
            T1.HorizontalAlignment = Element.ALIGN_CENTER;
            T1.VerticalAlignment = Element.ALIGN_MIDDLE;
            h1.AddCell(T1);

            Font underlineFont = new Font(baseFont, 10, Font.BOLD | Font.UNDERLINE);
            PdfPCell A2 = new PdfPCell(new Phrase("Khoa: " + dtb.Rows[0]["ScienceName"].ToString(), new Font(baseFont, 10, Font.BOLD)));
            A2.Border = Rectangle.NO_BORDER;
            A2.HorizontalAlignment = Element.ALIGN_CENTER;
            A2.VerticalAlignment = Element.ALIGN_MIDDLE;
            h1.AddCell(A2);

            PdfPCell T2 = new PdfPCell(new Phrase("Độc Lập - Tự Do - Hạnh Phúc", underlineFont));
            T2.Border = Rectangle.NO_BORDER;
            T2.HorizontalAlignment = Element.ALIGN_CENTER;
            T2.VerticalAlignment = Element.ALIGN_MIDDLE;
            h1.AddCell(T2);

            return h1;
        }

        public static string GetYearID(DataTable dtb)
        {
            return dtb.Rows[0]["YearID"].ToString() + " - " + (Convert.ToInt32(dtb.Rows[0]["YearID"]) + 1).ToString();
        }

        public static void AddFooterDate(PdfWriter writer, BaseFont baseFont)
        {
            PdfContentByte canvas = writer.DirectContent;
            string today = "Ngày in: " + DateTime.Now.ToString("dd-MM-yyyy HH:mm:ss");
            canvas.BeginText();
            canvas.SetFontAndSize(baseFont, 10);
            canvas.SetTextMatrix(20, 30);
            canvas.ShowText(today);
            canvas.EndText();
        }

        public static void SaveAndDownload(MemoryStream memoryStream, DataTable dtb, string suffix,
            HttpServerUtility server, HttpResponse response, DCore.SessionUser objUser)
        {
            string classID = dtb.Rows[0]["ClassID"].ToString();
            string subjectID = dtb.Rows[0]["SubjectID"].ToString();
            string timestamp = DateTime.Now.ToString("HHmmss");
            string baseFileName = classID + "_" + subjectID + "_" + timestamp + "_" + suffix + ".pdf";
            string filePath = server.MapPath("~\\Export\\" + baseFileName);

            string directoryPath = Path.GetDirectoryName(filePath);
            if (!Directory.Exists(directoryPath))
            {
                Directory.CreateDirectory(directoryPath);
            }

            if (File.Exists(filePath))
            {
                File.Delete(filePath);
            }

            File.WriteAllBytes(filePath, memoryStream.ToArray());

            response.Redirect(DCore.Globals.ApplicationVRoot + "/DownloadFile.ashx?key=" +
                DownloadFile.GenerateKeyForExport(filePath, baseFileName, objUser.UserName, "Viet$minh"));
        }

        // Helper tạo PdfPCell nhanh
        public static PdfPCell NewCell(string text, Font font, int alignment, int border)
        {
            PdfPCell cell = new PdfPCell(new Phrase(text, font));
            cell.HorizontalAlignment = alignment;
            cell.Border = border;
            return cell;
        }

        public static PdfPCell NewCellNoBorder(string text, Font font, int alignment)
        {
            return NewCell(text, font, alignment, Rectangle.NO_BORDER);
        }

        // Helper tạo info row - 2 cột
        public static PdfPTable NewInfoRow(BaseFont baseFont, int fontSize, 
            string leftText, string rightText)
        {
            PdfPTable table = new PdfPTable(2);
            table.WidthPercentage = 100;
            table.SetWidths(new float[] { 6f, 4f });

            Font f = new Font(baseFont, fontSize, Font.NORMAL);

            PdfPCell cellLeft = new PdfPCell(new Phrase(leftText, f));
            cellLeft.Border = Rectangle.NO_BORDER;
            cellLeft.PaddingLeft = 15f;
            cellLeft.PaddingBottom = 5f;
            cellLeft.HorizontalAlignment = Element.ALIGN_LEFT;
            table.AddCell(cellLeft);

            PdfPCell cellRight = new PdfPCell(new Phrase(rightText, f));
            cellRight.Border = Rectangle.NO_BORDER;
            cellRight.PaddingBottom = 5f;
            cellRight.HorizontalAlignment = Element.ALIGN_LEFT;
            table.AddCell(cellRight);

            return table;
        }

        // Helper tạo info row - 3 cột
        public static PdfPTable NewInfoRow3(BaseFont baseFont, int fontSize,
            string col1Text, string col2Text, string col3Text)
        {
            PdfPTable table = new PdfPTable(3);
            table.WidthPercentage = 100;
            table.SetWidths(new float[] { 3f, 3f, 4f });

            Font f = new Font(baseFont, fontSize, Font.NORMAL);

            PdfPCell c1 = new PdfPCell(new Phrase(col1Text, f));
            c1.Border = Rectangle.NO_BORDER;
            c1.PaddingLeft = 15f;
            c1.HorizontalAlignment = Element.ALIGN_LEFT;
            table.AddCell(c1);

            PdfPCell c2 = new PdfPCell(new Phrase(col2Text, f));
            c2.Border = Rectangle.NO_BORDER;
            c2.HorizontalAlignment = Element.ALIGN_LEFT;
            table.AddCell(c2);

            PdfPCell c3 = new PdfPCell(new Phrase(col3Text, f));
            c3.Border = Rectangle.NO_BORDER;
            c3.HorizontalAlignment = Element.ALIGN_LEFT;
            table.AddCell(c3);

            return table;
        }

        // Footer chữ ký 2 cột: Trưởng khoa | Giáo viên / Người lập
        public static PdfPTable BuildFooterSign2Col(BaseFont baseFont, string rightTitle)
        {
            PdfPTable table = new PdfPTable(2);
            table.WidthPercentage = 100;
            table.SetWidths(new float[] { 5f, 5f });

            PdfPCell empty1 = new PdfPCell(new Phrase(""));
            empty1.Border = Rectangle.NO_BORDER;
            empty1.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(empty1);

            PdfPCell dateCell = new PdfPCell(new Phrase("Gia Lai, ngày..... tháng ..... năm 20...", new Font(baseFont, 12, Font.NORMAL)));
            dateCell.Border = Rectangle.NO_BORDER;
            dateCell.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(dateCell);

            PdfPCell title1 = new PdfPCell(new Phrase("Trưởng khoa", new Font(baseFont, 12, Font.BOLD)));
            title1.Border = Rectangle.NO_BORDER;
            title1.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(title1);

            PdfPCell title2 = new PdfPCell(new Phrase(rightTitle, new Font(baseFont, 12, Font.BOLD)));
            title2.Border = Rectangle.NO_BORDER;
            title2.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(title2);

            return table;
        }

        // Footer chữ ký 3 cột: Trưởng ban | Tiểu ban | Giáo viên coi thi
        public static PdfPTable BuildFooterSign3Col(BaseFont baseFont)
        {
            PdfPTable table = new PdfPTable(3);
            table.WidthPercentage = 100;
            table.SetWidths(new float[] { 3f, 3f, 3f });

            // Row 1
            PdfPCell B1 = new PdfPCell(new Phrase("Trưởng ban chấm thi", new Font(baseFont, 12, Font.BOLD)));
            B1.Border = Rectangle.NO_BORDER;
            B1.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B1);

            PdfPCell B12 = new PdfPCell(new Phrase("Tiểu ban chấm thi", new Font(baseFont, 12, Font.BOLD)));
            B12.Border = Rectangle.NO_BORDER;
            B12.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B12);

            PdfPCell B13 = new PdfPCell(new Phrase("Giáo viên coi thi", new Font(baseFont, 12, Font.BOLD)));
            B13.Border = Rectangle.NO_BORDER;
            B13.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B13);

            // Row 2
            PdfPCell B2 = new PdfPCell(new Phrase(""));
            B2.Border = Rectangle.NO_BORDER;
            B2.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B2);

            PdfPCell B21 = new PdfPCell(new Phrase(""));
            B21.Border = Rectangle.NO_BORDER;
            B21.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B21);

            PdfPCell B23 = new PdfPCell(new Phrase("(Ký, ghi rõ họ tên)", new Font(baseFont, 10, Font.ITALIC)));
            B23.Border = Rectangle.NO_BORDER;
            B23.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B23);

            // Row 3
            PdfPCell B3 = new PdfPCell(new Phrase(""));
            B3.Border = Rectangle.NO_BORDER;
            B3.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B3);

            PdfPCell B32 = new PdfPCell(new Phrase(""));
            B32.Border = Rectangle.NO_BORDER;
            B32.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B32);

            PdfPCell B31 = new PdfPCell(new Phrase("1."));
            B31.Border = Rectangle.NO_BORDER;
            B31.HorizontalAlignment = Element.ALIGN_LEFT;
            B31.PaddingTop = 15f;
            B31.PaddingBottom = 20f;
            table.AddCell(B31);

            // Row 4
            PdfPCell B4 = new PdfPCell(new Phrase(""));
            B4.Border = Rectangle.NO_BORDER;
            B4.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B4);

            PdfPCell B41 = new PdfPCell(new Phrase(""));
            B41.Border = Rectangle.NO_BORDER;
            B41.HorizontalAlignment = Element.ALIGN_CENTER;
            table.AddCell(B41);

            PdfPCell B42 = new PdfPCell(new Phrase("2."));
            B42.Border = Rectangle.NO_BORDER;
            B42.HorizontalAlignment = Element.ALIGN_LEFT;
            B42.PaddingTop = 20f;
            table.AddCell(B42);

            return table;
        }
    }
}

